import heapq


def _ledger(priority, tax_base):
    def solve(data):
        cutoff = data.get("cutoff", 10**9)
        winners = {}
        for position, event in enumerate(data["events"]):
            sequence = event.get("sequence", 0)
            if sequence > cutoff:
                continue
            event_id = event.get("id", f"anonymous:{position}")
            if priority == "sequence_first":
                key = (sequence, event.get("revision", 0), position)
            else:
                key = (event.get("revision", 0), position)
            if event_id not in winners or key > winners[event_id][0]:
                winners[event_id] = (key, event)

        balances = dict(data.get("opening", {}))
        mode = data["rounding"]

        def rounded(numerator):
            if mode == "half_up":
                return (numerator + 5000) // 10000
            return numerator // 10000

        for _, event in winners.values():
            if event.get("void", False):
                continue
            raw = event["price"] * event.get("quantity", 1)
            discount = min(10000, max(0, event.get("discount_bp", 0)))
            net = rounded(raw * (10000 - discount))
            base = raw if tax_base == "original" else net
            tax = rounded(base * event.get("tax_bp", 0))
            amount = net + tax
            if event.get("kind") == "refund":
                amount = -amount
            key = event.get("account", "default") + "|" + event.get("currency", "USD")
            balances[key] = balances.get(key, 0) + amount
        return {"balances": balances}
    return solve


def _dependency_resolver(data):
    packages = data["packages"]
    names = sorted(packages, reverse=True)
    features = set(data.get("features", []))
    blocked = data.get("blocked", {})
    pins = data.get("pins", {})
    rows = {name: {row["version"]: row for row in versions}
            for name, versions in packages.items()}
    best = None
    best_key = None

    choices = [list(rows[name]) for name in names]
    for versions in product(*choices):
        assigned = dict(zip(names, versions))
        constraints = {name: [bounds] for name, bounds in data["roots"].items()}
        pending = list(data["roots"])
        installed = set()
        graph = {}
        valid = True
        while pending and valid:
            name = pending.pop()
            if name in installed:
                continue
            installed.add(name)
            version = assigned[name]
            if (version in blocked.get(name, []) or
                    (name in pins and pins[name] != version) or
                    any(not low <= version <= high
                        for low, high in constraints.get(name, []))):
                valid = False
                break
            deps = []
            for dep in rows[name][version].get("deps", []):
                feature = dep.get("feature", "")
                if feature and feature not in features:
                    continue
                deps.append(dep["name"])
                constraints.setdefault(dep["name"], []).append(
                    (dep["min"], dep["max"]))
                pending.append(dep["name"])
            graph[name] = deps

        if not valid:
            continue
        for name in installed:
            version = assigned[name]
            if any(not low <= version <= high
                   for low, high in constraints.get(name, [])):
                valid = False
                break
        if not valid:
            continue

        state = {}

        def visit(name):
            if state.get(name) == 1:
                return False
            if state.get(name) == 2:
                return True
            state[name] = 1
            for other in graph.get(name, []):
                if not visit(other):
                    return False
            state[name] = 2
            return True

        if any(not visit(name) for name in installed):
            continue
        result = {name: assigned[name] for name in installed}
        key = tuple(result.get(name, -1) for name in names)
        if best_key is None or key < best_key:
            best_key, best = key, result

    if best is None:
        return {"error": "unsatisfiable"}
    return {"versions": best}


def _quota_intervals(data):
    jobs = data["jobs"]
    k = data["k"]
    blocked = set(data.get("blocked", []))
    mandatory = set(data.get("mandatory", []))
    quotas = data.get("quotas", {})
    available = [job for job in jobs if job["id"] not in blocked]
    best_value = None
    best_ids = None

    for subset in combinations(available, k):
        ids = [job["id"] for job in subset]
        if not mandatory.issubset(ids):
            continue
        counts = {}
        for job in subset:
            counts[job["group"]] = counts.get(job["group"], 0) + 1
        if any(not low <= counts.get(group, 0) <= high
               for group, (low, high) in quotas.items()):
            continue
        ordered = sorted(subset, key=lambda job: (job["start"], job["end"], job["id"]))
        if any(ordered[i]["start"] < ordered[i - 1]["end"]
               for i in range(1, len(ordered))):
            continue
        value = sum(job["value"] for job in subset)
        sorted_ids = sorted(ids)
        if (best_value is None or value > best_value or
                (value == best_value and sorted_ids > best_ids)):
            best_value, best_ids = value, sorted_ids

    if best_value is None:
        return {"error": "impossible"}
    return {"selected": best_ids, "value": best_value}


def _temporal_routes(data):
    required = data.get("required", [])
    bits = {node: 1 << i for i, node in enumerate(required)}
    full = (1 << len(required)) - 1
    source = data["source"]
    initial_mask = bits.get(source, 0)
    start_state = (source, initial_mask, 0)
    distances = {start_state: data["start"]}
    queue = [(data["start"], source, initial_mask, 0)]
    graph = [[] for _ in range(data["n"])]
    for edge in data["edges"]:
        graph[edge["u"]].append(edge)

    while queue:
        time, node, mask, used = heapq.heappop(queue)
        state = (node, mask, used)
        if distances.get(state) != time:
            continue
        if node == data["target"] and mask == full and used == data["coupons"]:
            return {"arrival": time}
        for edge in graph[node]:
            depart = max(time, edge["open"])
            if depart >= edge["close"]:
                continue
            options = [(edge["duration"], used)]
            if used < data["coupons"]:
                duration = max(1, edge["duration"] - edge.get("discount", 0))
                options.append((duration, used + 1))
            for duration, next_used in options:
                arrival = depart + duration
                if arrival > data["deadline"]:
                    continue
                next_node = edge["v"]
                next_mask = mask | bits.get(next_node, 0)
                next_state = (next_node, next_mask, next_used)
                if arrival < distances.get(next_state, float("inf")):
                    distances[next_state] = arrival
                    heapq.heappush(queue, (arrival, next_node, next_mask, next_used))
    return {"arrival": None}


